#pragma once

// The generator is in editor builds, and in game builds made with `aot_generator=yes`: a game
// generates code for its own platform's bytecode layout (32-bit platforms such as the web need
// code generated by a 32-bit build; see tools/aot.py).
#if defined(TOOLS_ENABLED) || defined(GODOT_AS_AOT_GENERATOR)
#define ASAOT_GENERATOR 1
#endif

#ifdef ASAOT_GENERATOR

#include <angelscript.h>
#include <godot_cpp/variant/dictionary.hpp>
#include <godot_cpp/variant/string.hpp>

namespace asaot {

// Writes C++ for every script function of `p_module` to `p_path` (see aot_runtime.h). The module
// must have been compiled with asEP_INCLUDE_JIT_INSTRUCTIONS. Returns false with r_error set on
// failure; fills r_report with counts (functions, instructions, native_instructions).
bool generate(asIScriptModule *p_module, const godot::String &p_path, godot::Dictionary &r_report, godot::String &r_error);

} // namespace asaot

#endif
